}

function draw() {
  translate(-width / 2, -height / 2);
  background("#f4efe4");
  // Painting the sky
  brush.fill("#2874aa", 60); // Sky blue
  brush.beginShape();
  brush.vertex(0, 0);
  brush.vertex(400, 0);
  brush.vertex(200, 400);
  brush.endShape(true);
  // Painting the hills
  brush.fill("#3d8695", 40); // Light green
  brush.beginShape();
  brush.vertex(0, 400);
  brush.vertex(400, 400);
  brush.vertex(200, 0);
  brush.endShape(true);
  // Painting the sun
  brush.fill("#f99d26", 100); // Warm yellow
  brush.beginShape();
  brush.vertex(200, 200);
  brush.vertex(250, 180);
  brush.vertex(200, 160);
  brush.endShape(true);
  // Painting the clouds
  brush.fill("#f3e8d2", 30); // Light grey
  brush.beginShape();
  brush.vertex(100, 200);
  brush.vertex(200, 150);
  brush.vertex(300, 200);
  brush.endShape(true);
  // Painting the lake
  brush.fill("#759797", 20); // Light blue
  brush.beginShape();
  brush.vertex(150, 170);
  brush.vertex(170, 210);
  brush.vertex(140, 230);
  brush.vertex(120, 220);
  brush.vertex(130, 190);
  brush.endShape(true);
  // Painting the sun's rays
  brush.fill("#f99d26", 70); // Warm yellow
  brush.beginShape();
  brush.vertex(200, 200);
  brush.vertex(220, 180);
  brush.vertex(240, 200);
  brush.vertex(260, 180);
  brush.vertex(280, 200);
  brush.endShape(true);
}
